<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,type Envelope} from '@/api'
import {scoreText} from '@/evaluation/model'
import {ElMessage,ElMessageBox} from 'element-plus'
import '@/styles/evaluation-center.css'
const groups=ref<any[]>([]),selected=ref<any>(),loading=ref(false)
async function load(){groups.value=(await api.get<any,Envelope<any[]>>('/evaluation/revisions')).data}
async function inspect(row:any){loading.value=true;try{selected.value=(await api.post<any,Envelope<any>>(`/evaluation/revisions/${row.id}/refresh`)).data}finally{loading.value=false}}
async function publish(){await ElMessageBox.confirm('将同时发布组内月评及相关季评，原版本保留在历史记录中。确认发布？','发布关联修订');await api.post(`/evaluation/revisions/${selected.value.id}/publish`,{reviewToken:selected.value.reviewToken});ElMessage.success('关联修订已成组发布');selected.value=null;await load()}
async function waive(row:any){const reason=(await ElMessageBox.prompt('填写缺项豁免原因','管理员核定')).value;const score=Number((await ElMessageBox.prompt('输入0至100的综合分，最多两位小数','核定分数',{inputPattern:/^(100(?:\.0{1,2})?|\d{1,2}(?:\.\d{1,2})?)$/})).value);selected.value=(await api.post<any,Envelope<any>>(`/evaluation/revisions/${selected.value.id}/waivers`,{summaryId:row.summary_id,reason,score})).data;ElMessage.success('已记录管理员核定')}
onMounted(load)
</script>
<template><div class="evaluation-module-page" v-loading="loading"><header class="evaluation-page-head"><div><span class="eyebrow">综合评价 · 关联修订审核</span><h1>关联修订审核</h1><p>跨月调整、补交补考或答辩修订影响已发布结果时，在此核对并成组发布。</p></div><el-button @click="load">刷新</el-button></header><section class="evaluation-workspace"><el-table :data="groups" empty-text="暂无待审核关联修订"><el-table-column prop="id" label="修订组" width="90"/><el-table-column prop="reason" label="原因" min-width="220"/><el-table-column prop="member_count" label="关联汇总数"/><el-table-column prop="creator_name" label="创建人"/><el-table-column prop="created_at" label="创建时间"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="inspect(s.row)">刷新并核对</el-button></template></el-table-column></el-table></section><section v-if="selected" class="evaluation-workspace"><div class="evaluation-workspace-head"><h2>修订组 #{{selected.id}}</h2><el-button @click="inspect(selected)">重新计算</el-button></div><el-alert title="原正式版本在本组发布前保持有效；评分来源发生变化时，系统会要求重新核对。" type="info" :closable="false"/><el-table :data="selected.members"><el-table-column prop="employee_no" label="工号"/><el-table-column prop="employee_name" label="姓名"/><el-table-column prop="period_key" label="期间"/><el-table-column label="类型"><template #default="s">{{s.row.summary_type==='MONTH'?'月度':'季度'}}</template></el-table-column><el-table-column prop="version" label="新版本"/><el-table-column label="原综合分"><template #default="s">{{scoreText(s.row.old_final_score)}}</template></el-table-column><el-table-column label="新综合分"><template #default="s">{{scoreText(s.row.final_score)}}</template></el-table-column><el-table-column label="待处理"><template #default="s">{{s.row.revision_override_score!=null?'已核定豁免：'+s.row.waiver_reason:s.row.error_message||s.row.missing_items||'已完整'}}<el-button v-if="s.row.missing_items&&!s.row.error_message" link @click="waive(s.row)">管理员核定</el-button></template></el-table-column></el-table><el-button type="primary" :disabled="selected.members.some((r:any)=>r.error_message||(r.missing_items&&r.revision_override_score==null)||r.final_score==null)" @click="publish">成组审核发布</el-button></section></div></template>
